CREATE TABLE t3x(id INTEGER PRIMARY KEY,w TEXT); CREATE TABLE t4x(id INTEGER PRIMARY KEY,x TEXT); CREATE TABLE t5x(id INTEGER PRIMARY KEY,y TEXT); CREATE TABLE t6x(id INTEGER PRIMARY KEY,z INT); CREATE VIEW dual(dummy) AS VALUES('x'); INSERT INTO t3x(id,w) VALUES(2,'two'),(3,'three'),(6,'six'),(7,'seven'); INSERT INTO t4x(id,x) VALUES(2,'alice'),(4,'bob'),(6,'cindy'),(8,'dave'); INSERT INTO t5x(id,y) VALUES(1,'red'),(2,'orange'),(3,'yellow'),(4,'green'),(5,'blue'); INSERT INTO t6x(id,z) VALUES(3,333),(4,444),(5,555),(0,1000),(9,999); CREATE VIEW t3 AS SELECT * FROM t3x LIMIT 1000; CREATE VIEW t4 AS SELECT * FROM t4x LIMIT 1000; CREATE VIEW t5 AS SELECT * FROM t5x LIMIT 1000; CREATE VIEW t6 AS SELECT * FROM t6x LIMIT 1000;